import path from "node:path";
import { build } from "esbuild";
import type { Plugin } from "esbuild";

const ROOT = path.resolve(__dirname, "../..");
const ENTRY = "src/lib/report-issue/server-entry.ts";
const LIVE_JSON = path.join(ROOT, "src/lib/report-issue/live-json.ts");

/** The committed bundle the Supabase functions import. */
export const ENGINE_FILE = path.join(
  ROOT,
  "supabase/functions/_shared/report-engine.js",
);

const BANNER = [
  "// generated by npm run engine:bundle; do not edit",
  '// @ts-self-types="./report-engine.d.ts"',
].join("\n");

/** The checked-in files that become live holders, and the holder each reads. */
const LIVE_FILES: Record<string, string> = {
  [path.join(ROOT, "src/data/manifest.json")]: "liveManifest",
  [path.join(ROOT, "src/data/occupation-index.json")]: "liveIndex",
};

/**
 * Points the manifest and index imports at live-json.ts, whose holders the
 * engine fills with the month it is handed, and refuses any other JSON: the
 * rules, cores and details arrive as EngineData, never bundled.
 */
const liveData: Plugin = {
  name: "live-data",
  setup(bundle) {
    bundle.onResolve({ filter: /\.json$/ }, (args) => {
      const file = path.resolve(args.resolveDir, args.path);
      const holder = LIVE_FILES[file];
      if (holder) return { path: holder, namespace: "live-data" };
      return {
        errors: [
          {
            text: `The report engine must not embed ${path.relative(ROOT, file)}; pass it in EngineData`,
          },
        ],
      };
    });
    bundle.onLoad({ filter: /.*/, namespace: "live-data" }, (args) => ({
      contents: `export { ${args.path} as default } from ${JSON.stringify(LIVE_JSON)};`,
      loader: "ts",
      resolveDir: ROOT,
    }));
  },
};

/** Bundles the server engine into `outfile`; returns the source files it read. */
export async function bundleEngine(
  outfile: string,
): Promise<{ inputs: string[] }> {
  const result = await build({
    absWorkingDir: ROOT,
    entryPoints: [ENTRY],
    outfile,
    bundle: true,
    format: "esm",
    platform: "neutral",
    target: "es2022",
    minify: false,
    charset: "utf8",
    legalComments: "none",
    banner: { js: BANNER },
    plugins: [liveData],
    metafile: true,
    logLevel: "warning",
  });
  const inputs = Object.keys(result.metafile.inputs).filter(
    (file) => !file.startsWith("live-data:"),
  );
  return { inputs };
}

if (process.argv[1]?.endsWith("bundle.ts")) {
  bundleEngine(ENGINE_FILE).then(
    ({ inputs }) => {
      const file = path.relative(ROOT, ENGINE_FILE);
      console.log(`engine:bundle: wrote ${file} from ${inputs.length} files`);
    },
    (error: unknown) => {
      console.error(error instanceof Error ? error.message : error);
      process.exitCode = 1;
    },
  );
}
